// Lollipop Chart — Comparison, route: jsx
// Source: original:gaps/lollipop
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from lollipop ----
// Share of electricity from renewables, by country. Hardcoded plausible values —
// the long labels are the point: they justify the horizontal layout.
const renewableShare: { name: string; value: number }[] = [
  { name: 'Norway', value: 0.98 },
  { name: 'Brazil', value: 0.89 },
  { name: 'New Zealand', value: 0.87 },
  { name: 'Colombia', value: 0.74 },
  { name: 'Canada', value: 0.68 },
  { name: 'Portugal', value: 0.61 },
  { name: 'Germany', value: 0.52 },
  { name: 'United Kingdom', value: 0.47 },
  { name: 'Spain', value: 0.46 },
  { name: 'China', value: 0.31 },
  { name: 'United States', value: 0.23 },
  { name: 'India', value: 0.22 },
  { name: 'Japan', value: 0.21 },
  { name: 'South Korea', value: 0.09 }
];

const ROW_HEIGHT = 24;
const MARGIN = { top: 8, right: 44, bottom: 34, left: 108 };
const DOT_RADIUS = 5;

const format = d3.format('.0%');

/** One lollipop per row, sorted by value before drawing. */
export type Data = { name: string; value: number }[];

export default function LollipopChart({ data = renewableShare, width }: { data?: Data; width: number }) {
  const sorted = useMemo(() => [...data].sort((a, b) => b.value - a.value), [data]);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = sorted.length * ROW_HEIGHT;
  const height = innerHeight + MARGIN.top + MARGIN.bottom;

  const x = useMemo(
    () =>
      d3
        .scaleLinear()
        .domain([0, d3.max(sorted, (d) => d.value) ?? 1])
        .nice()
        .range([0, Math.max(innerWidth, 0)]),
    [sorted, innerWidth]
  );

  const y = useMemo(
    () =>
      d3
        .scaleBand<string>()
        .domain(sorted.map((d) => d.name))
        .range([0, innerHeight])
        .padding(0.1),
    [sorted, innerHeight]
  );

  const xTicks: Tick[] = useMemo(
    () =>
      x.ticks(Math.max(2, Math.round(innerWidth / 80))).map((v) => ({
        value: format(v),
        offset: x(v)
      })),
    [x, innerWidth]
  );

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Lollipop chart of renewable electricity share by country, sorted descending"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {sorted.map((d) => {
          const middle = (y(d.name) ?? 0) + y.bandwidth() / 2;
          return (
            <g key={d.name}>
              <text x={-8} y={middle} dy="0.32em" textAnchor="end" fontSize={11} fill="var(--text)">
                {d.name}
              </text>
              <line x1={0} x2={x(d.value)} y1={middle} y2={middle} stroke="var(--muted)" />
              <circle cx={x(d.value)} cy={middle} r={DOT_RADIUS} fill="var(--accent)" />
              <text
                x={x(d.value) + DOT_RADIUS + 4}
                y={middle}
                dy="0.32em"
                fontSize={10}
                fill="var(--text)"
              >
                {format(d.value)}
              </text>
            </g>
          );
        })}
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
      </g>
    </svg>
  );
}
